/bin/bash -c "node <<'NODE'
const assert = require('node:assert/strict')
const origin = 'http://127.0.0.1:3107'
const checks = [
  { path: '/', title: 'Home Page', description: 'Welcome to our Next.js app', heading: 'Home', link: '/about' },
  { path: '/about', title: 'About Us', description: 'Learn more about us', heading: 'About', link: '/' },
]
;(async () => {
  for (const check of checks) {
    const response = await fetch(origin + check.path)
    const html = await response.text()
    assert.equal(response.status, 200)
    assert.match(html, /<html lang=\"en\">/)
    assert.match(html, new RegExp("'`<title>${check.title}</title>`))
    assert.match(html, new RegExp(`<meta name="description" content="${check.description}"`))
    assert.match(html, new RegExp(`<h1>${check.heading}</h1>`))
    assert.ok(html.includes(`href="${check.link}"`))
    console.log(`${check.path}: HTTP ${response.status}, title, metadata, heading, link OK`)
  }
  const response = await fetch(origin + '"'/contact')
  assert.equal(response.status, 404)
  console.log('/contact: HTTP 404 (unchanged)')
})().catch(error => { console.error(error); process.exitCode = 1 })
NODE"

